private string Evaluate(string title, string employer, string location, string arrangement, string description, string payMin, string payMax, string skillsRequired, string skillsMissing, string setting1, string setting2, string setting3, out string note)
{
    note = "";
    var text = (title + "\n" + description).ToLowerInvariant();
    var phrases = setting1.Split(',');
    for (var i = 0; i < phrases.Length; i++)
    {
        var phrase = phrases[i].Trim().ToLowerInvariant();
        if (phrase.Length > 0 && ContainsPhrase(text, phrase))
        {
            note = "mentions \"" + phrase + "\"";
            return "exclude";
        }
    }
    return "pass";
}

private bool ContainsPhrase(string text, string phrase)
{
    var at = text.IndexOf(phrase, StringComparison.Ordinal);
    while (at >= 0)
    {
        var end = at + phrase.Length;
        var before = at == 0 || !char.IsLetterOrDigit(text[at - 1]);
        var after = end == text.Length || !char.IsLetterOrDigit(text[end]);
        if (before && after)
            return true;
        at = text.IndexOf(phrase, at + 1, StringComparison.Ordinal);
    }
    return false;
}
